// Fichier, date et participants (une ligne par personne : Nom, rôle, email).
const src = $('Déposer l\'enregistrement').first();
const fichier = Object.values(src.binary ?? {})[0];
if (!fichier) throw new Error('Aucun fichier reçu.');
const participants = String(src.json.participants ?? '').split('\n').map(l => l.split(',').map(s => s.trim())).filter(p => p[0])
  .map(([nom, role = '', email = '']) => ({ nom, prenom: nom.split(' ')[0], role, email: /@/.test(email) ? email : '' }));
const date = src.json.date || $now.toISODate();
return [{ json: { titre: src.json.titre || 'Réunion', date, participants, vocabulaire: String(src.json.vocabulaire ?? '').trim(), nom_fichier: fichier.fileName }, binary: { data: fichier } }];

// Transcription repérée [MM:SS] pour l'IA, et texte brut pour l'archive.
const t = $input.first().json;
const segs = t.segments ?? [];
if (!segs.length) throw new Error('Transcription vide : l\'enregistrement contient-il de la parole ?');
const mmss = s => String(Math.floor(s / 60)).padStart(2, '0') + ':' + String(Math.floor(s % 60)).padStart(2, '0');
return [{ json: { texte: t.text, reperee: segs.map(s => `[${mmss(s.start)}] ${s.text.trim()}`).join('\n'), duree_s: Math.round(segs[segs.length - 1].end), duree: mmss(segs[segs.length - 1].end), temps_transcription_s: t.temps_de_calcul_s ?? null } }];

