// Contrôles, puis fichiers joints : compte rendu (Markdown), échéances (.ics), transcription (.txt).
const r = $('Préparer').first().json;
const tr = $('Transcription repérée').first().json;
const cr = $('Rédiger le compte rendu').first().json.output;
const prenoms = new Map(r.participants.map(p => [p.prenom.toLowerCase(), p]));
const sec = s => { const m = /^(\d{1,3}):(\d{2})$/.exec(String(s ?? '').trim()); return m ? +m[1] * 60 + +m[2] : NaN; };
const jour = d => DateTime.fromISO(d).setLocale('fr').toFormat('cccc d LLLL');
const taches = (cr.taches ?? []).map(t => {
  const p = prenoms.get(String(t.responsable ?? '').trim().split(' ')[0].toLowerCase());
  const ech = /^\d{4}-\d{2}-\d{2}$/.test(t.echeance ?? '') ? t.echeance : '';
  const alertes = [];
  if (!p) alertes.push('responsable à désigner');
  else if (t.attribution !== 'explicite') alertes.push('responsable à confirmer');
  if (!ech) alertes.push('échéance à préciser');
  else if (ech < r.date) alertes.push('échéance antérieure à la réunion');
  if (isNaN(sec(t.horodatage)) || sec(t.horodatage) > tr.duree_s + 5) alertes.push('horodatage invalide');
  return { tache: t.tache, responsable: p ? p.prenom : '', email: p?.email ?? '', echeance: ech, echeance_lisible: ech ? jour(ech) : '', horodatage: t.horodatage, alertes };
});
const aVerifier = taches.filter(t => t.alertes.length).length;

const md = ['# ' + r.titre + ' · ' + DateTime.fromISO(r.date).setLocale('fr').toFormat('cccc d LLLL yyyy'), '',
  '*Participants : ' + r.participants.map(p => p.nom + (p.role ? ' (' + p.role + ')' : '')).join(', ') + ' · durée ' + tr.duree + '*', '',
  '## Résumé', '', cr.resume, '', '## Décisions', '', ...(cr.decisions ?? []).map(d => '- ' + d), '',
  '## Tâches', '', '| Tâche | Responsable | Échéance | Repère |', '|---|---|---|---|',
  ...taches.map(t => `| ${t.tache} | ${t.responsable ? t.responsable + (t.alertes.includes('responsable à confirmer') ? ' (à confirmer)' : '') : '⚠ à désigner'} | ${t.echeance_lisible || '⚠ à préciser'} | ${t.horodatage} |`), '',
  '## Questions ouvertes', '', ...(cr.questions_ouvertes ?? []).map(q => '- ' + q), '',
  ...(cr.prochaine_reunion?.date ? ['## Prochaine réunion', '', jour(cr.prochaine_reunion.date) + (cr.prochaine_reunion.heure ? ' à ' + cr.prochaine_reunion.heure : ''), ''] : []),
].join('\n');

const ics = d => d.replace(/-/g, '');
const lendemain = d => DateTime.fromISO(d).plus({ days: 1 }).toISODate().replace(/-/g, '');
const echap = s => String(s).replace(/[\\;,]/g, m => '\\' + m).replace(/\n/g, ' ');
const stamp = $now.toUTC().toFormat("yyyyMMdd'T'HHmmss'Z'");
const evts = taches.filter(t => t.echeance).map((t, i) => ['BEGIN:VEVENT', 'UID:' + r.date + '-' + i + '@chene-et-cie.demo', 'DTSTAMP:' + stamp,
  'DTSTART;VALUE=DATE:' + ics(t.echeance), 'DTEND;VALUE=DATE:' + lendemain(t.echeance),
  'SUMMARY:' + echap('Échéance · ' + t.tache + (t.responsable ? ' (' + t.responsable + ')' : '')),
  'DESCRIPTION:' + echap('Tâche décidée lors de « ' + r.titre + ' » du ' + r.date + ', à ' + t.horodatage + ' de l\'enregistrement.'), 'END:VEVENT']);
if (cr.prochaine_reunion?.date && /^\d{2}:\d{2}$/.test(cr.prochaine_reunion.heure ?? '')) {
  const debut = DateTime.fromISO(cr.prochaine_reunion.date + 'T' + cr.prochaine_reunion.heure, { zone: 'Europe/Paris' });
  evts.push(['BEGIN:VEVENT', 'UID:prochaine-' + r.date + '@chene-et-cie.demo', 'DTSTAMP:' + stamp, 'DTSTART:' + debut.toUTC().toFormat("yyyyMMdd'T'HHmmss'Z'"),
    'DTEND:' + debut.plus({ minutes: 30 }).toUTC().toFormat("yyyyMMdd'T'HHmmss'Z'"), 'SUMMARY:' + echap('Prochaine réunion · ' + r.titre), 'END:VEVENT']);
}
const calendrier = ['BEGIN:VCALENDAR', 'VERSION:2.0', 'PRODID:-//VudeLao//Compte rendu de reunion//FR', 'CALSCALE:GREGORIAN', ...evts.flat(), 'END:VCALENDAR'].join('\r\n');

const f = async (txt, nom, type) => await this.helpers.prepareBinaryData(Buffer.from(txt, 'utf8'), nom, type);
const base = 'reunion-' + r.date;
return [{ json: { titre: r.titre, date: r.date, date_lisible: DateTime.fromISO(r.date).setLocale('fr').toFormat('cccc d LLLL yyyy'), duree: tr.duree,
    participants: r.participants, destinataires: r.participants.map(p => p.email).filter(Boolean).join(','),
    resume: cr.resume, decisions: cr.decisions ?? [], taches, questions_ouvertes: cr.questions_ouvertes ?? [],
    prochaine: cr.prochaine_reunion?.date ? jour(cr.prochaine_reunion.date) + (cr.prochaine_reunion.heure ? ' à ' + cr.prochaine_reunion.heure : '') : '',
    a_verifier: aVerifier },
  binary: {
    compte_rendu: await f(md, base + '-compte-rendu.md', 'text/markdown'),
    agenda: await f(calendrier, base + '-echeances.ics', 'text/calendar'),
    transcription: await f(tr.reperee, base + '-transcription.txt', 'text/plain'),
  } }];
